// Safqa Toolbox: hundreds of offline tools generated from parametrized
// templates. Every tool runs in the browser; prices come from the last synced
// snapshot and FX rates from the last cached daily rates (shown with dates).
import type { ProductCard } from '@safqa/shared';

export type Values = Record<string, number | string>;
export interface Field { id: string; ar: string; en: string; kind?: 'number' | 'select' | 'date' | 'product'; def: number | string; unit?: string; options?: [string, string][]; step?: number; min?: number; category?: string }
export interface Row { ar: string; en: string; value: string; big?: boolean; good?: boolean; bad?: boolean }
export interface Ctx { fx: Record<string, number> | null; fxDate: string | null; products: ProductCard[]; specOf: (id: string) => Record<string, unknown> }
export interface Tool { id: string; cat: CatId; emoji: string; ar: string; en: string; dar: string; den: string; fields: Field[]; run: (v: Values, ctx: Ctx) => { rows: Row[]; noteAr?: string; noteEn?: string }; tags?: string }
export type CatId = 'money' | 'installments' | 'currency' | 'units' | 'energy' | 'unitprice' | 'specs' | 'sizing' | 'dates' | 'everyday';

export const toolCats: { id: CatId; ar: string; en: string; emoji: string }[] = [
  { id: 'money', ar: 'أدوات الصفقات والفلوس', en: 'Deal & money tools', emoji: '💰' },
  { id: 'installments', ar: 'حاسبات التقسيط والفايدة', en: 'Installments & interest', emoji: '🧾' },
  { id: 'currency', ar: 'محوّل العملات (أسعار متخزنة)', en: 'Currency (cached rates)', emoji: '💱' },
  { id: 'energy', ar: 'تكلفة الكهرباء للأجهزة', en: 'Appliance power cost', emoji: '⚡' },
  { id: 'unitprice', ar: 'مقارنة سعر الوحدة', en: 'Unit-price comparers', emoji: '⚖️' },
  { id: 'specs', ar: 'مقارنات المواصفات والاختيار', en: 'Spec comparers & pickers', emoji: '📊' },
  { id: 'sizing', ar: 'أدلة المقاسات والاختيار', en: 'Size & fit guides', emoji: '📏' },
  { id: 'units', ar: 'تحويل الوحدات', en: 'Unit converters', emoji: '🔁' },
  { id: 'dates', ar: 'مواعيد وضمان واسترجاع', en: 'Dates, warranty & returns', emoji: '📅' },
  { id: 'everyday', ar: 'حسابات يومية', en: 'Everyday math', emoji: '🧮' },
];

const n = (v: Values, k: string) => Number(v[k]) || 0;
const egp = (x: number) => `${Math.round(x).toLocaleString('en-US')} ج`;
const f2 = (x: number, d = 2) => (Number.isFinite(x) ? x.toLocaleString('en-US', { maximumFractionDigits: d }) : '—');
const pct = (x: number) => `${f2(x, 1)}%`;
const F = (id: string, ar: string, en: string, def: number | string, unit?: string, extra: Partial<Field> = {}): Field => ({ id, ar, en, def, unit, kind: 'number', ...extra });
const R = (ar: string, en: string, value: string, extra: Partial<Row> = {}): Row => ({ ar, en, value, ...extra });

const tools: Tool[] = [];
const add = (t: Tool) => tools.push(t);

// ------------------------------------------------------------------ money
add({ id: 'real-discount', cat: 'money', emoji: '🏷️', ar: 'نسبة الخصم الحقيقية', en: 'Real discount %', dar: 'اعرف الخصم الفعلي من السعر قبل وبعد', den: 'Actual discount from before/after price', fields: [F('was', 'السعر قبل', 'Was', 20000, 'ج'), F('now', 'السعر بعد', 'Now', 16999, 'ج')], run: (v) => { const d = n(v, 'was') - n(v, 'now'); return { rows: [R('الخصم', 'Discount', pct((d / n(v, 'was')) * 100), { big: true, good: d > 0 }), R('وفّرت', 'Saved', egp(d))] }; } });
add({ id: 'fake-discount', cat: 'money', emoji: '🕵️', ar: 'كاشف الخصم المضروب', en: 'Fake-discount detector', dar: 'قارن "السعر قبل الخصم" بأعلى سعر حقيقي شفته', den: 'Compare the claimed "was" price with the highest real price seen', fields: [F('was', 'السعر قبل (المكتوب)', 'Claimed was', 25000, 'ج'), F('now', 'السعر دلوقتي', 'Now', 19999, 'ج'), F('high', 'أعلى سعر حقيقي في 90 يوم', 'Highest real 90d', 21000, 'ج'), F('median', 'متوسط آخر 30 يوم', '30-day median', 20500, 'ج')], run: (v) => { const inflated = n(v, 'was') > n(v, 'high') * 1.05; const illusory = n(v, 'now') >= n(v, 'median') * 0.98; const claimed = (1 - n(v, 'now') / n(v, 'was')) * 100; const real = (1 - n(v, 'now') / n(v, 'median')) * 100; return { rows: [R('الحكم', 'Verdict', inflated || illusory ? '⚠️ مشبوه' : '✅ حقيقي', { big: true, bad: inflated || illusory, good: !(inflated || illusory) }), R('الخصم المكتوب', 'Claimed', pct(claimed)), R('الخصم الحقيقي مقابل المتوسط', 'Real vs median', pct(real)), R('سعر "قبل" مضخّم؟', 'Inflated was?', inflated ? 'أيوه' : 'لأ'), R('السعر مش أقل من المتوسط؟', 'Not under median?', illusory ? 'أيوه' : 'لأ')], noteAr: 'نفس منطق كاشف صفقة: "قبل" أعلى من أعلى سعر فعلي بـ5%، أو "بعد" مش أقل من المتوسط.' }; } });
add({ id: 'deal-score', cat: 'money', emoji: '🎯', ar: 'درجة الصفقة', en: 'Deal score', dar: 'درجة من 100 من السعر مقابل المتوسط والقاع', den: '0–100 score vs median and low', fields: [F('now', 'السعر', 'Price', 15000, 'ج'), F('median', 'المتوسط', 'Median', 16500, 'ج'), F('low', 'أقل سعر سجلته', 'Recorded low', 14500, 'ج'), F('rating', 'تقييم المتجر/المنتج', 'Rating', 4.4, '/5', { step: 0.1 })], run: (v) => { const vsMed = Math.max(-1, Math.min(1, (n(v, 'median') - n(v, 'now')) / n(v, 'median') / 0.25)); const vsLow = n(v, 'low') ? Math.max(0, 1 - (n(v, 'now') - n(v, 'low')) / n(v, 'low') / 0.2) : 0.5; const s = Math.round(Math.max(0, Math.min(100, 50 + vsMed * 30 + vsLow * 15 + (n(v, 'rating') - 4) * 10))); return { rows: [R('الدرجة', 'Score', `${s}/100`, { big: true, good: s >= 70, bad: s < 45 }), R('التقدير', 'Label', s >= 80 ? 'صفقة نار 🔥' : s >= 65 ? 'كويسة 👍' : s >= 45 ? 'عادية' : 'مش مستاهلة')] }; } });
add({ id: 'buy-or-wait', cat: 'money', emoji: '⏳', ar: 'أشتري دلوقتي ولا أستنى؟', en: 'Buy now or wait?', dar: 'قارن التوفير المتوقع بتكلفة الانتظار', den: 'Expected saving vs the cost of waiting', fields: [F('price', 'السعر الحالي', 'Price now', 20000, 'ج'), F('drop', 'نسبة النزول المتوقعة في الموسم', 'Expected seasonal drop', 12, '%'), F('prob', 'احتمال يحصل', 'Probability', 60, '%'), F('days', 'أيام الانتظار', 'Days to wait', 30), F('need', 'تكلفة إنك تستنى في اليوم', 'Daily cost of waiting', 20, 'ج')], run: (v) => { const gain = n(v, 'price') * (n(v, 'drop') / 100) * (n(v, 'prob') / 100); const cost = n(v, 'days') * n(v, 'need'); return { rows: [R('القرار', 'Decision', gain > cost ? 'استنى ⏳' : 'اشتري دلوقتي ✅', { big: true }), R('التوفير المتوقع', 'Expected saving', egp(gain)), R('تكلفة الانتظار', 'Cost of waiting', egp(cost))] }; } });
add({ id: 'stack', cat: 'money', emoji: '🧮', ar: 'تجميع خصومات (نسبة + مبلغ)', en: 'Stack discounts', dar: 'خصم نسبة وبعده كوبون مبلغ وبعده كاش باك', den: 'Percent then fixed coupon then cashback', fields: [F('price', 'السعر', 'Price', 10000, 'ج'), F('p1', 'خصم نسبة', 'Percent off', 10, '%'), F('cap', 'أقصى خصم للنسبة', 'Percent cap', 1000, 'ج'), F('amt', 'كوبون مبلغ', 'Fixed coupon', 200, 'ج'), F('cb', 'كاش باك', 'Cashback', 5, '%')], run: (v) => { const a = Math.min(n(v, 'price') * n(v, 'p1') / 100, n(v, 'cap') || Number.POSITIVE_INFINITY); const after = n(v, 'price') - a - n(v, 'amt'); const cb = after * n(v, 'cb') / 100; return { rows: [R('هتدفع', 'You pay', egp(after), { big: true }), R('بعد الكاش باك', 'Net after cashback', egp(after - cb), { good: true }), R('إجمالي التوفير', 'Total saved', egp(n(v, 'price') - after + cb))], noteAr: 'أكواد الكوبونات هنا مدخلاتك إنت — صفقة مش بيعرض كوبونات غير مؤكدة.' }; } });
add({ id: 'price-per-use', cat: 'money', emoji: '🔂', ar: 'السعر لكل استخدام', en: 'Price per use', dar: 'السعر ÷ عدد مرات الاستخدام المتوقع', den: 'Price ÷ expected uses', fields: [F('price', 'السعر', 'Price', 3000, 'ج'), F('per', 'مرات في الأسبوع', 'Uses per week', 5), F('years', 'سنين الاستخدام', 'Years', 2)], run: (v) => { const uses = n(v, 'per') * 52 * n(v, 'years'); return { rows: [R('لكل استخدام', 'Per use', egp(n(v, 'price') / uses), { big: true }), R('لكل يوم', 'Per day', egp(n(v, 'price') / (365 * n(v, 'years'))))] }; } });
add({ id: 'tco', cat: 'money', emoji: '🏁', ar: 'التكلفة الكلية للامتلاك', en: 'Total cost of ownership', dar: 'السعر + الكهرباء + الصيانة − سعر البيع بعدين', den: 'Price + energy + upkeep − resale', fields: [F('price', 'السعر', 'Price', 25000, 'ج'), F('energy', 'كهرباء في الشهر', 'Energy per month', 300, 'ج'), F('maint', 'صيانة في السنة', 'Upkeep per year', 500, 'ج'), F('years', 'سنين', 'Years', 5), F('resale', 'قيمة إعادة البيع', 'Resale value', 30, '%')], run: (v) => { const t = n(v, 'price') + n(v, 'energy') * 12 * n(v, 'years') + n(v, 'maint') * n(v, 'years') - n(v, 'price') * n(v, 'resale') / 100; return { rows: [R('التكلفة الكلية', 'Total cost', egp(t), { big: true }), R('في الشهر', 'Per month', egp(t / (12 * n(v, 'years'))))] }; } });
add({ id: 'two-tco', cat: 'money', emoji: '🥊', ar: 'رخيص مستهلك ولا غالي موفّر؟', en: 'Cheap & hungry vs pricey & efficient', dar: 'قارن جهازين بالسعر واستهلاك الكهرباء', den: 'Compare two devices by price and running cost', fields: [F('p1', 'سعر الأول', 'Price A', 18000, 'ج'), F('e1', 'كهرباء الأول/شهر', 'Energy A/mo', 450, 'ج'), F('p2', 'سعر التاني', 'Price B', 24000, 'ج'), F('e2', 'كهرباء التاني/شهر', 'Energy B/mo', 300, 'ج')], run: (v) => { const diff = n(v, 'p2') - n(v, 'p1'); const save = n(v, 'e1') - n(v, 'e2'); const months = save > 0 ? diff / save : Number.POSITIVE_INFINITY; return { rows: [R('الغالي بيعوّض فرقه بعد', 'Break-even after', Number.isFinite(months) ? `${f2(months, 1)} شهر` : 'مش هيعوّض', { big: true }), R('توفير 5 سنين', '5-year saving', egp(save * 60 - diff), { good: save * 60 - diff > 0 })] }; } });
add({ id: 'vat', cat: 'money', emoji: '🧾', ar: 'ضريبة القيمة المضافة 14%', en: 'VAT 14%', dar: 'أضف أو شيل ضريبة 14% من سعر', den: 'Add or remove Egypt’s 14% VAT', fields: [F('price', 'السعر', 'Price', 1000, 'ج'), F('rate', 'النسبة', 'Rate', 14, '%')], run: (v) => ({ rows: [R('بالضريبة', 'With VAT', egp(n(v, 'price') * (1 + n(v, 'rate') / 100)), { big: true }), R('من غير ضريبة (لو السعر شامل)', 'Ex-VAT (if inclusive)', egp(n(v, 'price') / (1 + n(v, 'rate') / 100))), R('قيمة الضريبة في السعر الشامل', 'VAT inside', egp(n(v, 'price') - n(v, 'price') / (1 + n(v, 'rate') / 100)))] }) });
add({ id: 'customs', cat: 'money', emoji: '🛃', ar: 'تقدير الجمارك والشحن من بره', en: 'Import customs & shipping estimate', dar: 'سعر بره + شحن + جمارك + ضريبة — تقديري وقابل للتعديل', den: 'Price abroad + shipping + duty + VAT — editable estimate', fields: [F('usd', 'السعر بالدولار', 'Price (USD)', 500, '$'), F('rate', 'سعر الدولار', 'USD rate', 49, 'ج'), F('ship', 'الشحن بالدولار', 'Shipping (USD)', 30, '$'), F('duty', 'نسبة الجمارك', 'Customs duty', 20, '%'), F('vat', 'ضريبة القيمة المضافة', 'VAT', 14, '%'), F('fees', 'رسوم أخرى', 'Other fees', 300, 'ج'), F('local', 'سعره في مصر', 'Local price', 30000, 'ج')], run: (v) => { const base = (n(v, 'usd') + n(v, 'ship')) * n(v, 'rate'); const duty = base * n(v, 'duty') / 100; const vat = (base + duty) * n(v, 'vat') / 100; const total = base + duty + vat + n(v, 'fees'); return { rows: [R('التكلفة واصل', 'Landed cost', egp(total), { big: true }), R('مقابل السعر المحلي', 'vs local', total < n(v, 'local') ? `أوفر بـ ${egp(n(v, 'local') - total)}` : `أغلى بـ ${egp(total - n(v, 'local'))}`, { good: total < n(v, 'local'), bad: total >= n(v, 'local') }), R('الجمارك', 'Duty', egp(duty)), R('الضريبة', 'VAT', egp(vat))], noteAr: 'نسب الجمارك بتختلف حسب الصنف والقرارات الحكومية — دي قيم افتراضية عدّلها حسب حالتك. الموبايلات ليها قواعد خاصة (تسجيل الجهاز).' }; } });
add({ id: 'cashback', cat: 'money', emoji: '💳', ar: 'قيمة الكاش باك والنقاط', en: 'Cashback & points value', dar: 'كام بترجعلك فعلًا', den: 'What you really get back', fields: [F('spend', 'المشتريات الشهرية', 'Monthly spend', 8000, 'ج'), F('cb', 'نسبة الكاش باك', 'Cashback', 2, '%'), F('fee', 'رسوم الكارت السنوية', 'Annual fee', 600, 'ج')], run: (v) => { const y = n(v, 'spend') * 12 * n(v, 'cb') / 100 - n(v, 'fee'); return { rows: [R('صافي في السنة', 'Net per year', egp(y), { big: true, good: y > 0, bad: y <= 0 })] }; } });
add({ id: 'free-ship', cat: 'money', emoji: '🚚', ar: 'أضيف حاجة علشان الشحن المجاني؟', en: 'Add an item for free shipping?', dar: 'قارن رسوم الشحن بالحاجة الزيادة', den: 'Shipping fee vs the filler item', fields: [F('cart', 'السلة', 'Cart', 420, 'ج'), F('min', 'حد الشحن المجاني', 'Free-shipping min', 500, 'ج'), F('fee', 'رسوم الشحن', 'Shipping fee', 50, 'ج'), F('need', 'هتستخدم الحاجة الزيادة؟ (0-100%)', 'Will you use the filler? (%)', 50, '%')], run: (v) => { const gap = Math.max(0, n(v, 'min') - n(v, 'cart')); const waste = gap * (1 - n(v, 'need') / 100); return { rows: [R('القرار', 'Decision', gap === 0 ? 'الشحن مجاني أصلًا ✅' : waste < n(v, 'fee') ? 'ضيف حاجة 👍' : 'ادفع الشحن', { big: true }), R('الفرق للحد', 'Gap to minimum', egp(gap))] }; } });
add({ id: 'bundle', cat: 'money', emoji: '📦', ar: 'باكدج ولا كل حاجة لوحدها؟', en: 'Bundle vs separate', dar: 'هل العرض المجمع أوفر فعلًا؟', den: 'Is the bundle really cheaper?', fields: [F('b', 'سعر الباكدج', 'Bundle price', 12000, 'ج'), F('a1', 'المنتج 1 لوحده', 'Item 1', 9000, 'ج'), F('a2', 'المنتج 2 لوحده', 'Item 2', 3500, 'ج'), F('a3', 'المنتج 3 لوحده (0 لو مفيش)', 'Item 3 (0 if none)', 0, 'ج'), F('use', 'هتستخدم كل حاجة؟ (%)', 'Will use all? (%)', 100, '%')], run: (v) => { const sep = n(v, 'a1') + n(v, 'a2') + n(v, 'a3'); const eff = sep * n(v, 'use') / 100; return { rows: [R('النتيجة', 'Result', n(v, 'b') < eff ? `الباكدج أوفر بـ ${egp(eff - n(v, 'b'))}` : `اشتري لوحدهم — أوفر بـ ${egp(n(v, 'b') - eff)}`, { big: true })] }; } });
