add({ id: 'save-goal', cat: 'everyday', emoji: '🐷', ar: 'هوصل لهدف الادخار امتى؟', en: 'Savings goal timeline', dar: 'كام شهر علشان تشتري الحاجة كاش', den: 'Months to buy it in cash', fields: [F('goal', 'سعر الحاجة', 'Target price', 25000, 'ج'), F('have', 'معاك', 'Saved', 5000, 'ج'), F('month', 'هتحوش في الشهر', 'Per month', 3000, 'ج'), F('yield', 'عائد شهادة/حساب سنوي', 'Annual yield', 20, '%')], run: (v) => { let bal = n(v, 'have'); let m = 0; const r = n(v, 'yield') / 1200; while (bal < n(v, 'goal') && m < 600) { bal = bal * (1 + r) + n(v, 'month'); m++; } return { rows: [R('هتوصل بعد', 'Reached in', m >= 600 ? '—' : `${m} شهر`, { big: true }), R('مقابل التقسيط', 'vs installments', 'الكاش غالبًا أوفر لو مفيش 0% فايدة')] }; } });
