export const tariffNote = 'شرائح الاستهلاك المنزلي (جدول أغسطس 2024): 0–50: 0.68، 51–100: 0.78، 0–200: 0.95، 201–350: 1.55، 351–650: 1.95، 651–1000: 2.10، أكتر من 1000: 2.23 ج/ك.و.س — اتأكد من آخر تعديل على فاتورتك.';
function billFor(kwh: number): number {
  if (kwh <= 50) return kwh * 0.68;
  if (kwh <= 100) return 50 * 0.68 + (kwh - 50) * 0.78;
  if (kwh <= 200) return kwh * 0.95;
  if (kwh <= 350) return 200 * 0.95 + (kwh - 200) * 1.55;
  if (kwh <= 650) return 200 * 0.95 + 150 * 1.55 + (kwh - 350) * 1.95;
  if (kwh <= 1000) return kwh * 2.1;
  return kwh * 2.23;
}
